mapper.select:
SELECT x.id AS id, x.express_id AS expressId, e.express_no AS expressNo, e.receiver_name AS receiverName, e.receiver_phone AS receiverPhone, e.status AS expressStatus, x.exception_type AS exceptionType, x.description AS description, x.image_url AS imageUrl, x.reporter_id AS reporterId, ru.real_name AS reporterName, x.handler_id AS handlerId, hu.real_name AS handlerName, x.handle_status AS handleStatus, x.handle_remark AS handleRemark, DATE_FORMAT(x.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, DATE_FORMAT(x.handle_time, '%Y-%m-%d %H:%i:%s') AS handleTime, DATE_FORMAT(x.update_time, '%Y-%m-%d %H:%i:%s') AS updateTime FROM express_exception x LEFT JOIN express e ON e.id = x.express_id LEFT JOIN sys_user ru ON ru.id = x.reporter_id LEFT JOIN sys_user hu ON hu.id = x.handler_id WHERE 1 = 1
AND x.express_id = #{expressId}
AND x.exception_type = #{exceptionType}
AND x.handle_status = #{handleStatus}
AND x.reporter_id = #{reporterId}
AND (e.express_no LIKE CONCAT('%', #{keyword}, '%') OR e.receiver_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY x.id DESC
